def max_profit(n, k, a):
    dp = [[0]*k for _ in range(n)]
    for j in range(k):
        dp[0][j] = a[0]
    for i in range(1, n):
        dp[i][0] = max(dp[i-1][0], a[i])
        for j in range(1, min(i+1, k)):
            dp[i][j] = max(max(dp[i-1][j], dp[i-1][j-1] + a[i]), a[i])

    def reconstruct(n, k):
        if n == 0:
            return []
        if k == 1:
            return [n]
        if dp[n][k] == dp[n-1][k]:
            return reconstruct(n-1, k)
        elif dp[n][k] == dp[n-1][k-1] + a[n]:
            return [reconstruct(n-1, k-1)[0]+1] + reconstruct(n-1, k-1)[1:]
        else:
            return [1] + reconstruct(n-1, k)

    max_profit_value = dp[-1][-1]
    days = reconstruct(n, k)
    return max_profit_value, days

# Example usage:
if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:]))

    max_profit_value, days = max_profit(n, k, a)
    print(max_profit_value)
    print(' '.join(map(str, days)))
